def import_dae(suffix):
    cleanup()
    bpy.ops.wm.collada_import(filepath =
        fr"/Users/jarrett/Library/Application Support/Project Prime/Samus_lod1/Samus_lod1_{suffix}.dae")
    set_common()
    set_texture_alpha('Gun_mat', 31, False)
    set_back_culling('Gun_mat')
    set_mat_color('Gun_mat', 1, 1, 1, False, [])
    set_texture_alpha('GunTip_mat', 31, False)
    set_back_culling('GunTip_mat')
    set_mat_color('GunTip_mat', 1, 1, 1, False, [])
    set_texture_alpha('body_mat', 31, False)
    set_back_culling('body_mat')
    set_mat_color('body_mat', 1, 1, 1, False, [])
    set_texture_alpha('body_full_bright_mat', 31, False)
    set_back_culling('body_full_bright_mat')
    set_mat_color('body_full_bright_mat', 1, 1, 1, False, [])
    bone_setup()
    anim_setup()

